   138	 * Name: bk7258_camera_line_batch_done
   139	 *
   140	 * Description:
   141	 *   YUV_BUF ping-pong bank-done callback (invoked from
   142	 *   bk7258_yuv_buf.c's ISR context for every 8-line batch).  Issues one
   143	 *   DMA copy of that bank's fixed PSRAM contents into the frame buffer
   144	 *   at the current running offset, then advances the offset.  When the
   145	 *   offset reaches a full frame's worth of bytes, invokes the
   146	 *   imgdata_capture_t callback to report frame completion and resets
   147	 *   for the next frame.
   148	 *
   149	 ****************************************************************************/
   150	
   151	static void bk7258_camera_line_batch_done(bk7258_yuv_buf_bank_t bank,
   152	                                           void *arg)
   153	{
   154	  FAR struct bk7258_camera_imgdata_s *priv = arg;
   155	  uint32_t line_buf_addr = bk7258_yuv_buf_get_line_buf_addr();
   156	  uint32_t batch_bytes = bk7258_yuv_buf_get_line_batch_bytes();
   157	  uint32_t src_addr;
   158	  struct timeval ts;
   159	
   160	  if (!priv->capturing || priv->frame_buf == NULL)
   161	    {
   162	      return;
   163	    }
   164	
   165	  if (priv->frame_offset + batch_bytes > priv->frame_buf_size)
   166	    {
   167	      /* Should not happen once validate_frame_setting()/set_buf() have
   168	       * agreed on BK7258_CAMERA_FRAME_BYTES, but guard against a
   169	       * mismatched buffer size overrunning it -- drop this batch and
   170	       * resynchronize at the next frame boundary rather than corrupting
   171	       * memory past the buffer, mirroring bk_dvp.c's yuv_sm0_line_done()/
   172	       * yuv_sm1_line_done() offset-overflow guard (which resets
   173	       * yuv_data_offset to 0 and sets handle->error). */
   174	      priv->frame_offset = 0;
   175	      return;
   176	    }
   177	
   178	  /* SM0 reads from the ping-pong region at offset 0; SM1 reads from the
   179	   * region at offset +batch_bytes -- matching yuv_sm0_line_done()'s
   180	   * yuv_em_addr and yuv_sm1_line_done()'s "yuv_em_addr +
   181	   * yuv_pingpong_length" source addresses. */
   182	  src_addr = line_buf_addr;
   183	  if (bank == BK7258_YUV_BUF_BANK_SM1)
   184	    {
   185	      src_addr += batch_bytes;
   186	    }
   187	
   188	  /* Not waiting for a previous DMA to finish before starting this one:
   189	   * bk7258_dma_configure() unconditionally disables the channel first,
   190	   * matching bk_dvp.c's bk_dma_stop() + reconfigure + bk_dma_start()
   191	   * pattern in both line-done handlers -- see this file's header
   192	   * comment for the timing assumption this depends on. */
   193	  bk7258_dma_configure(src_addr,
   194	                        (uint32_t)(uintptr_t)(priv->frame_buf +
   195	                                               priv->frame_offset),
   196	                        batch_bytes);
