   198	
   199	  priv->frame_offset += batch_bytes;
   200	
   201	  if (priv->frame_offset >= priv->frame_buf_size)
   202	    {
   203	      priv->frame_offset = 0;
   204	
   205	      if (priv->capture_cb != NULL)
   206	        {
   207	          gettimeofday(&ts, NULL);
   208	          printf("bk7258_camera_imgdata: frame complete, %u bytes\n",
   209	                 (unsigned int)priv->frame_buf_size);
   210	          priv->capture_cb(OK, priv->frame_buf_size, &ts,
   211	                            priv->capture_cb_arg);
   212	        }
   213	    }
   214	}
